<script setup lang="ts">import { onMounted, ref } from "vue"; import { useRoute, useRouter } from "vue-router"; import { staffSession } from "../../auth/session"; import { listStores, type Store } from "../../admin/api"; import { lowStock, type Item } from "../api"; const route = useRoute(); const router = useRouter(); const items = ref<Item[]>([]); const stores = ref<Store[]>([]); const storeId = ref(String(route.query.storeId ?? "")); async function load(): Promise<void> { items.value = await lowStock(storeId.value || undefined); } async function changeStore(): Promise<void> { await router.replace({ query: storeId.value ? { storeId: storeId.value } : {} }); await load(); } onMounted(async () => { if (staffSession.value?.user.role === "admin") stores.value = (await listStores()).filter((store) => store.active); await load(); });</script><template><section><header><div><p class="eyebrow">Almacen</p><h1>Alertas de stock</h1></div></header><div class="filter-bar"><select v-if="staffSession?.user.role === 'admin'" v-model="storeId" @change="changeStore"><option value="">Selecciona una tienda</option><option v-for="store in stores" :key="store.id" :value="store.id">{{ store.name }}</option></select><RouterLink :to="{ name: 'inventory.list', query: storeId ? { storeId } : {} }">Volver al almacén</RouterLink></div><div class="customer-list"><p v-if="!items.length" class="empty">No hay alertas de stock bajo.</p><RouterLink v-else v-for="item in items" :key="item.id" class="customer-row" :to="{ name: 'inventory.detail.general', params: { id: item.id }, query: storeId ? { storeId } : {} }"><strong>{{ item.name }}</strong><span>{{ item.sku }}</span><span>{{ item.stock }} {{ item.unit }}</span><span class="status-pill">Min. {{ item.minimumStock }}</span></RouterLink></div></section></template>